db.ratings.aggregate([
  {
    $group: { _id: "$movieId", v: { $sum: 1 }, R: { $avg: "$rating" } }
  },
  { $match: { v: { $gte: 50 } } },
  {
    $addFields: {
      weighted: {
        $add: [
          {
            $multiply: [{ $divide: ["$v", { $add: ["$v", 50] }] }, "$R"]
          },
          {
            $multiply: [{ $divide: [50, { $add: ["$v", 50] }] }, 3.5]
          }
        ]
      }
    }
  },
  { $sort: { weighted: -1 } },
  { $limit: 10 },
  {
    $lookup: {
      from: "movies",
      localField: "_id",
      foreignField: "movieId",
      as: "movie"
    }
  },
  { $unwind: "$movie" },
  {
    $project: {
      _id: 0,
      title: "$movie.title",
      votes: "$v",
      avgRating: { $round: ["$R", 2] },
      weightedRating: { $round: ["$weighted", 3] }
    }
  }
])

